export function getTierForRow(row) {
  if (!row) return null;
  const pin = String(
    row['Pincode'] || row['pincode'] || row['PINCODE'] ||
    row['Pin Code'] || row['pin code'] || row['ZIP'] || row['zip'] || ''
  ).trim().replace(/\D/g, '');
  if (pin && PINCODE_TIER[pin]) return PINCODE_TIER[pin];
  const dist = String(
    row['District'] || row['district'] || row['DISTRICT'] || ''
  ).trim().toUpperCase();
  if (dist && DISTRICT_TIER[dist]) return DISTRICT_TIER[dist];
  const city = String(row['City'] || row['city'] || '').trim().toUpperCase();
  if (city && DISTRICT_TIER[city]) return DISTRICT_TIER[city];
  return null;
}